import os
import sys

root = os.getcwd()
print("CWD:", root)
for entry in sorted(os.listdir(root)):
    full = os.path.join(root, entry)
    if os.path.isfile(full):
        print(f"FILE  {entry}  ({os.path.getsize(full)} bytes)")
    elif os.path.isdir(full):
        print(f"DIR   {entry}/")

# Check common locations for report.pdf
candidates = [
    os.path.join(root, "report.pdf"),
    os.path.join(root, "Reports", "report.pdf"),
    os.path.join(root, "documents", "report.pdf"),
]
for c in candidates:
    if os.path.exists(c):
        print("FOUND:", c)

